// Runes Reforged: the stat-shard tables and the shard icon sets.
//
// Everything per patch lives elsewhere (DESIGN §1.6, §2.1):
//   - the listed patches, their season, label, Data Dragon version and
//     shard era: patch-registry.js (LOL_PATCHES.reforged), read through
//     lol-data.js (LolPatches);
//   - the client's own rune texts where Data Dragon left @Variable@
//     placeholders, and the V7.22-V8.22 path-pair bonus: the extras files
//     data/reforged/rr-*.js ({perkText, subStyleBonus}), loaded with
//     LolData.load(entry) (generated by tools/build-reforged.js);
//   - the rune catalog itself: Data Dragon
//     https://ddragon.leagueoflegends.com/cdn/{ddragonVersion}/data/en_US/runesReforged.json,
//     fetched at runtime by runes-reforged.js.
// Live patches 25.x / 26.x are Data Dragon 15.x / 16.x (Riot kept the
// sequential majors there); the registry entry carries the real version.
//
// Milestones the tables below follow: V7.22 (Nov 2017) Runes Reforged
// launch, with the path-pair bonus instead of stat shards; V8.6 Conqueror
// added (Precision's fourth keystone); V8.23 stat shards replace the
// path-pair bonus; V10.23 the scaling CDR shard becomes +8 Ability Haste;
// V14.2 shard rework (Move Speed, flat Health, Tenacity and Slow Resist).
//
// Sources: CommunityDragon <branch>/plugins/rcp-be-lol-game-data/global/
// default/v1/perkstyles.json (kStatMod slots) + perks.json (texts), per era
// in data/sources/reforged/shard-eras.json; Riot patch notes; the LoL wiki
// Rune patch history.

// The shard icons were redrawn twice, so each era loads its own set,
// vendored from CommunityDragon's statmods folder of that branch. The sets
// differ in one icon each; the cut-offs are where the client's art changed
// (CommunityDragon perks.json iconPath + statmods art, branch by branch):
//   "2018"   V8.23-V12.10      pink magic resist, axe attack speed
//   "2022"   V12.11-V25.14     cyan magic resist (12.11 switches to
//                              StatModsMagicResIcon.MagicResist_Fix.png; 13.x
//                              draws the same art under the old name); move
//                              speed / health / tenacity as of 14.19
//   "latest" V25.19 (15.19)+   sword attack speed (the 15.18 art; 15.15 still
//                              has the axe, 15.16-15.17 an in-between icon on
//                              unlisted patches only)
var REFORGED_SHARD_ICON_DIR = "images/runes-reforged/statmods/";
function getReforgedShardIconUrl(dataSet, icon) {
    var p = String(dataSet && dataSet.ddragonVersion || "").split(".");
    var major = parseInt(p[0], 10) || 99, minor = parseInt(p[1], 10) || 0;
    var set = (major < 12 || (major === 12 && minor < 11)) ? "2018"
        : (major < 15 || (major === 15 && minor < 18)) ? "2022" : "latest";
    return REFORGED_SHARD_ICON_DIR + set + "/" + icon;
}

// Stat shards (V8.23+): three rows of three, one pick per row. The options
// and their numbers changed seven times; each era id is the registry
// entry's `shardEra` (DESIGN §3.2; null for V7.22-V8.22, which had none):
//   s8-23   V8.23-V8.24   launch: Adaptive 10, Attack Speed 9%, 1-10% CDR;
//                         Armor 5, Magic Resist 6; scaling Health 15-90
//   s9-1    V9.1          Attack Speed 9% -> 10%
//   s9-2    V9.2-V10.22   Adaptive 10 -> 9, Armor 5 -> 6, Magic Resist 6 -> 8
//   s10-23  V10.23-V11.20 scaling CDR -> +8 Ability Haste
//   s11-21  V11.21-V14.1  scaling Health 15-90 -> 15-140
//   s14-2   V14.2-V25.21  rework: flex Adaptive / 2% Move Speed / 10-180
//                         scaling Health; defense 65 Health / 10% Tenacity
//                         and Slow Resist / 10-180 scaling Health
//   s25-22  V25.22+       Move Speed 2.5%, Tenacity and Slow Resist 15%;
//                         scaling Health stays 10-180
// `desc` is the client's text for the era (perks.json, markup dropped);
// REFORGED_SHARD_TEXT_BY_PATCH below keeps the one wording slip inside an
// era. `name` is the tooltip title: the client's shard name (perks.json
// `name`, V12.22+; earlier branches carry internal ids such as
// "HealthScaling", so the same shard keeps its later client name there).
// tools/build-reforged.js (F1) checks these rows, numbers, texts and names
// against CommunityDragon for every listed patch; tools/check-patches.js
// (F1) checks the rows and numbers.
var reforgedShardEras = (function(){
    var ICON = {
        adaptive: "statmodsadaptiveforceicon.png", as: "statmodsattackspeedicon.png",
        cdr: "statmodscdrscalingicon.png", armor: "statmodsarmoricon.png", mr: "statmodsmagicresicon.png",
        // Named after the client's files: healthScaling = the plain heart,
        // healthPlus = the heart with an arrow (see reworked() for who uses which).
        healthScaling: "statmodshealthscalingicon.png", healthPlus: "statmodshealthplusicon.png",
        ms: "statmodsmovementspeedicon.png", tenacity: "statmodstenacityicon.png"
    };
    function s(id, name, desc, icon) { return { id: id, name: name, desc: desc, icon: ICON[icon] }; }
    function rows(offense, flex, defense) {
        return { rows: [
            { id: "offense", label: "Offense", shards: offense },
            { id: "flex", label: "Flex", shards: flex },
            { id: "defense", label: "Defense", shards: defense }
        ] };
    }
    // The pre-V14.2 rows differ only in their numbers.
    function classic(o) {
        var af = s("5008", "Adaptive Force", "+" + o.af + " Adaptive Force", "adaptive");
        var armor = s("5002", "Armor", "+" + o.armor + " Armor", "armor");
        var mr = s("5003", "Magic Resist", "+" + o.mr + " Magic Resist", "mr");
        return rows(
            [af, s("5005", "Attack Speed", "+" + o.as + "% Attack Speed", "as"), o.haste
                ? s("5007", "Ability Haste", "+8 Ability Haste", "cdr")
                : s("5007", "Scaling CDR", "+1-10% CDR (based on level)", "cdr")],
            [af, armor, mr],
            [s("5001", "Health Scaling", "+" + o.hp + " Health (based on level)", "healthScaling"), armor, mr]);
    }
    // V14.2+. The rework swapped the two heart icons, as the client drew
    // them (CommunityDragon 14.2+ perks.json iconPath): scaling Health 5001
    // gets the heart with an arrow (StatModsHealthPlusIcon.png), the new flat
    // +65 Health 5011 the plain heart (StatModsHealthScalingIcon.png).
    // tools/build-reforged.js (F1) checks every shard icon against iconPath.
    function reworked(ms, tenacity) {
        var hp = s("5001", "Health Scaling", "+10-180 Health (based on level)", "healthPlus");
        return rows(
            [s("5008", "Adaptive Force", "+9 Adaptive Force", "adaptive"),
             s("5005", "Attack Speed", "+10% Attack Speed", "as"),
             s("5007", "Ability Haste", "+8 Ability Haste", "cdr")],
            [s("5008", "Adaptive Force", "+9 Adaptive Force", "adaptive"),
             s("5010", "Move Speed", "+" + ms + "% Move Speed", "ms"), hp],
            [s("5011", "Health", "+65 Health", "healthScaling"),
             s("5013", "Tenacity and Slow Resist", "+" + tenacity + "% Tenacity and Slow Resist", "tenacity"), hp]);
    }
    return {
        "s8-23":  classic({ af: 10, as: 9,  armor: 5, mr: 6, hp: "15-90" }),
        "s9-1":   classic({ af: 10, as: 10, armor: 5, mr: 6, hp: "15-90" }),
        "s9-2":   classic({ af: 9,  as: 10, armor: 6, mr: 8, hp: "15-90" }),
        "s10-23": classic({ af: 9,  as: 10, armor: 6, mr: 8, hp: "15-90", haste: true }),
        "s11-21": classic({ af: 9,  as: 10, armor: 6, mr: 8, hp: "15-140", haste: true }),
        "s14-2":  reworked(2, 10),
        "s25-22": reworked(2.5, 15)
    };
})();

// Client wording that differs from its era's text on one listed patch only
// (D3: the client's own slips are kept). V10.23 made the scaling CDR shard
// a flat +8 Ability Haste but kept "(based on level)"; V10.24 dropped it
// (CommunityDragon 10.23 / 10.24 perks.json 5007).
var REFORGED_SHARD_TEXT_BY_PATCH = {
    "V10.23": { "5007": "+8 Ability Haste (based on level)" }
};

// The shard rows of a dataset (registry entry), or null (V7.22-V8.22).
var reforgedShardRowsByPatch = {};
function getReforgedShardRows(dataSet) {
    if (!dataSet || !dataSet.shardEra) return null;
    var era = reforgedShardEras[dataSet.shardEra];
    if (!era) return null;
    var fix = REFORGED_SHARD_TEXT_BY_PATCH[dataSet.patch];
    if (!fix) return era.rows;
    var key = dataSet.shardEra + "|" + dataSet.patch;
    if (!reforgedShardRowsByPatch[key]) {
        reforgedShardRowsByPatch[key] = era.rows.map(function(row){
            return { id: row.id, label: row.label, shards: row.shards.map(function(sh){
                return fix[sh.id] ? { id: sh.id, name: sh.name, desc: fix[sh.id], icon: sh.icon } : sh;
            }) };
        });
    }
    return reforgedShardRowsByPatch[key];
}
